#pragma once
#include <map>
#include <string>
struct Preferences{ std::map<std::string,float> m; bool begin(const char*,bool){return true;} bool getBool(const char*k,bool d){return m.count(k)?m[k]!=0:d;} float getFloat(const char*k,float d){return m.count(k)?m[k]:d;} void putBool(const char*k,bool v){m[k]=v;} void putFloat(const char*k,float v){m[k]=v;} uint8_t getUChar(const char*k,uint8_t d){return m.count(k)?(uint8_t)m[k]:d;} void putUChar(const char*k,uint8_t v){m[k]=v;} std::map<std::string,uint64_t> u; uint32_t getULong(const char*k,uint32_t d){return u.count(k)?(uint32_t)u[k]:d;} void putULong(const char*k,uint32_t v){u[k]=v;} uint64_t getULong64(const char*k,uint64_t d){return u.count(k)?u[k]:d;} void putULong64(const char*k,uint64_t v){u[k]=v;} uint16_t getUShort(const char*k,uint16_t d){return u.count(k)?(uint16_t)u[k]:d;} void putUShort(const char*k,uint16_t v){u[k]=v; writes++;} int writes=0; };
